package com.cpf.starter.archive;import org.springframework.boot.context.properties.ConfigurationProperties;@ConfigurationProperties("cpf.file.archive") public class CpfArchiveProperties {private int maxEntries=10000;private long maxExpandedBytes=2L*1024*1024*1024;private double maxExpansionRatio=100;public int getMaxEntries(){return maxEntries;}public void setMaxEntries(int v){maxEntries=v;}public long getMaxExpandedBytes(){return maxExpandedBytes;}public void setMaxExpandedBytes(long v){maxExpandedBytes=v;}public double getMaxExpansionRatio(){return maxExpansionRatio;}public void setMaxExpansionRatio(double v){maxExpansionRatio=v;}public void validate(){if(maxEntries<1||maxExpandedBytes<1||maxExpansionRatio<1)throw new IllegalStateException("invalid archive limits");}}
